utils.waitForElement('.team-chat-anchor-outer').then(function (seeMore) {
  seeMore.insertAdjacentHTML('afterend', stepsHTML);
});

utils.waitForElement('.c-zigzag__content').then(function (firstBlock) {
  firstBlock.querySelector('.c-zigzag__header').textContent = secondHeader;
  firstBlock.querySelector('.c-zigzag__body').querySelector('p').textContent = secondDesc;
});

utils.waitForElement('.team-chat-quote').then(function (quoteContainer) {
  quoteContainer.querySelector('img').src = "https://her.one/cdn/shop/files/HER.ONE.Violet.png?v=1652447731";
  quoteContainer.querySelector('img').style = "height: 40px";
  quoteContainer.querySelector('.team-chat-quote-ital').textContent = quote;
  quoteContainer.querySelector('.team-chat-quote-attrib b').textContent = name;
  quoteContainer.querySelector('.team-chat-quote-role').textContent = `${designation}, ${company}, ${companyLocation}`;
});
utils.waitForElement('.c-accordion__row:nth-child(3)').then(function (faq) {
  faq.querySelector('.c-accordion__row__question').textContent = question1;
  faq.querySelector('.c-accordion__row__answer p').textContent = answer1;
});
utils.waitForElement('.c-accordion__row:nth-child(4)').then(function (faq) {
  faq.querySelector('.c-accordion__row__question').textContent = question2;
  faq.querySelector('.c-accordion__row__answer p').textContent = answer2;
});
